    {
      "id": "src:23",
      "url": "https://news.ycombinator.com/item?id=41207181",
      "title": "Hacker News comment by strken on the cost of collecting every event, on 'Is it time to version observability?'",
      "venue": "Hacker News. Comment text read via the HN Algolia API.",
      "speaker": "practitioner",
